    font-size: 1.5rem;
  }

  .gallery {
    grid-template-columns: 1fr;
  }
}

/* Ensure closed dialog is not visible or focusable */
dialog[open] {
  display: flex;
  align-items: center;
  justify-content: center;
}

dialog:not([open]) {
  display: none;
}
