document.addEventListener('DOMContentLoaded', () => {
  const dialog = document.getElementById('delete-confirm');
  const triggers = document.querySelectorAll('.trigger');
  const cancelBtn = dialog.querySelector('[data-action="cancel"]');
  const confirmBtn = dialog.querySelector('[data-action="confirm"]');

  let currentTrigger = null;

  // Open dialog when delete button is clicked
  triggers.forEach(trigger => {
    trigger.addEventListener('click', () => {
      currentTrigger = trigger;
      dialog.showModal();
      // Focus the cancel button by default (not the destructive action)
      cancelBtn.focus();
    });
  });

  // Close dialog when cancel button is clicked
  cancelBtn.addEventListener('click', () => {
    dialog.close('cancel');
  });

  // Handle delete confirmation
  confirmBtn.addEventListener('click', () => {
    dialog.close('confirm');
  });

  // Handle Escape key (native dialog behavior, but explicitly included for clarity)
  dialog.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      dialog.close('cancel');
    }
  });

  // Restore focus to the trigger when dialog closes
  dialog.addEventListener('close', () => {
    if (currentTrigger && document.contains(currentTrigger)) {
      currentTrigger.focus();
    }
    currentTrigger = null;
  });

  // Handle dialog result
  dialog.addEventListener('close', () => {
    const returnValue = dialog.returnValue;
    if (returnValue === 'confirm') {
      handleImageDeletion();
    }
  });

  // Function to handle image deletion
  function handleImageDeletion() {
    if (currentTrigger) {
      const imageCard = currentTrigger.closest('.image-card');
      if (imageCard) {
        // Animate removal
        imageCard.style.opacity = '0';
        imageCard.style.transform = 'scale(0.95)';

        setTimeout(() => {
          imageCard.remove();
        }, 200);
      }
    }
  }
});

