const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Load the HTML file
  const htmlPath = path.resolve(__dirname, 'index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

  // Test 1: Closed state
  console.log("=== Testing Closed State ===");
  await page.setContent(htmlContent, { waitUntil: 'load' });

  const axePath = require.resolve('axe-core/axe.min.js');
  await page.addScriptTag({ path: axePath });

  let results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  let wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  let bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log("Closed State - WCAG violations:", wcag.length);
  console.log("Closed State - Best-practice violations:", bp.length);

  // Test 2: Open state
  console.log("\n=== Testing Open State ===");

  // Reload to test open state
  await page.setContent(htmlContent, { waitUntil: 'load' });
  await page.addScriptTag({ path: axePath });

  // Open the modal
  await page.click('.trigger');
  await page.waitForTimeout(500);

  results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log("Open State - WCAG violations:", wcag.length);
  console.log("Open State - Best-practice violations:", bp.length);

  // Test 3: Keyboard navigation
  console.log("\n=== Testing Keyboard Navigation ===");

  await page.setContent(htmlContent, { waitUntil: 'load' });

  // Verify trigger button is focusable
  const triggerFocusable = await page.evaluate(() => {
    const trigger = document.querySelector('.trigger');
    return !trigger.hasAttribute('disabled') && trigger.tabIndex !== -1;
  });
  console.log("Trigger button is focusable:", triggerFocusable);

  // Open dialog with keyboard
  await page.click('.trigger');
  await page.waitForTimeout(500);

  const dialogOpen = await page.evaluate(() => {
    return document.querySelector('dialog').open;
  });
  console.log("Dialog opens with click:", dialogOpen);

  // Test Escape key closes dialog
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);

  const dialogClosed = await page.evaluate(() => {
    return !document.querySelector('dialog').open;
  });
  console.log("Escape key closes dialog:", dialogClosed);

  // Test focus is on trigger after close
  await page.click('.trigger');
  await page.waitForTimeout(500);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);

  const focusRestored = await page.evaluate(() => {
    const trigger = document.querySelector('.trigger');
    return document.activeElement === trigger;
  });
  console.log("Focus restored to trigger after close:", focusRestored);

  // Test 4: Semantic structure
  console.log("\n=== Testing Semantic Structure ===");

  const semanticValid = await page.evaluate(() => {
    const checks = {
      hasHeader: document.querySelector('header') !== null,
      hasMain: document.querySelector('main') !== null,
      hasH1: document.querySelector('h1') !== null,
      hasDialog: document.querySelector('dialog') !== null,
      dialogHasLabelledby: document.querySelector('dialog').hasAttribute('aria-labelledby'),
      dialogHasDescribedby: document.querySelector('dialog').hasAttribute('aria-describedby'),
      imagesHaveAlt: Array.from(document.querySelectorAll('img')).every(img => img.hasAttribute('alt') && img.alt.length > 0),
      buttonsHaveType: Array.from(document.querySelectorAll('button')).every(btn => btn.hasAttribute('type'))
    };
    return checks;
  });

  console.log("Semantic structure checks:", semanticValid);

  await browser.close();
})();
